package com.crm.designation.controller;
import com.crm.designation.entity.Designation; import com.crm.designation.repository.DesignationRepository; import com.crm.common.response.ApiResponse; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/designations") @RequiredArgsConstructor public class DesignationController{private final DesignationRepository repo;
@GetMapping public ApiResponse<List<Designation>> all(@RequestParam(required=false) Long companyId){List<Designation>d=companyId==null?repo.findAll():repo.findByCompanyId(companyId);return ApiResponse.<List<Designation>>builder().success(true).message("Designations fetched").data(d).build();}
@GetMapping("/{id}") public ApiResponse<Designation> get(@PathVariable Long id){return ApiResponse.<Designation>builder().success(true).message("Designation fetched").data(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Designation not found"))).build();}
@PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<Designation> create(@Valid @RequestBody Designation d){if(repo.existsByCode(d.getCode()))throw new IllegalArgumentException("Designation code already exists");return ApiResponse.<Designation>builder().success(true).message("Designation created").data(repo.save(d)).build();}
@PutMapping("/{id}") public ApiResponse<Designation> update(@PathVariable Long id,@Valid @RequestBody Designation d){Designation x=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Designation not found"));x.setName(d.getName());x.setCode(d.getCode());x.setCompanyId(d.getCompanyId());x.setDescription(d.getDescription());x.setActive(d.isActive());return ApiResponse.<Designation>builder().success(true).message("Designation updated").data(repo.save(x)).build();}
@DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){repo.deleteById(id);return ApiResponse.<Void>builder().success(true).message("Designation deleted").build();}}